class Solution:
    def validWordAbbreviation(self, word: str, abbr: str) -> bool:
        res = []
        i = 0
        while i < len(abbr):
            if abbr[i].isdigit():
                j = i
                while j < len(abbr) and abbr[j].isdigit():
                    j += 1
                num = abbr[i:j]
                if num[0] == '0':
                    return False
                res.append('*' * int(num))
                i = j
            else:
                res.append(abbr[i])
                i += 1
        s = ''.join(res)
        if len(s) != len(word):
            return False
        return all(c == '*' or c == w for c, w in zip(s, word))

