class Solution {
public:
    bool validWordAbbreviation(string word, string abbr) {
        string s;
        int i = 0;
        while (i < (int)abbr.size()) {
            if (isdigit(abbr[i])) {
                int j = i;
                long num = 0;
                if (abbr[i] == '0') return false;
                while (j < (int)abbr.size() && isdigit(abbr[j])) {
                    num = num * 10 + (abbr[j++] - '0');
                }
                s.append(num, '*');
                i = j;
            } else {
                s += abbr[i++];
            }
        }
        if (s.size() != word.size()) return false;
        for (int k = 0; k < (int)s.size(); k++)
            if (s[k] != '*' && s[k] != word[k]) return false;
        return true;
    }
};

