var validWordAbbreviation = function(word, abbr) {
    let parts = [];
    let i = 0;
    while (i < abbr.length) {
        if (/\d/.test(abbr[i])) {
            if (abbr[i] === '0') return false;
            let j = i;
            while (j < abbr.length && /\d/.test(abbr[j])) j++;
            parts.push('*'.repeat(Number(abbr.slice(i, j))));
            i = j;
        } else {
            parts.push(abbr[i++]);
        }
    }
    const s = parts.join('');
    if (s.length !== word.length) return false;
    for (let k = 0; k < s.length; k++)
        if (s[k] !== '*' && s[k] !== word[k]) return false;
    return true;
};

